def word_count(html: str) -> int:
    import re
    t = re.sub(r"<script[\s\S]*?</script>", " ", html)
    t = re.sub(r"<style[\s\S]*?</style>", " ", t)
    t = re.sub(r"<[^>]+>", " ", t)
    return len(t.split())


def main():
    for name, block in PAGES.items():
        path = CMP / name
        html = path.read_text(encoding="utf-8")
        if MARKER in html:
            print(f"skip {name} (already deep3)")
            continue
        if ANCHOR not in html:
            raise SystemExit(f"anchor missing in {name}")
        html = html.replace(ANCHOR, block.strip() + "\n" + ANCHOR, 1)
        path.write_text(html, encoding="utf-8")
        print(f"ok {name} words={word_count(html)}")


if __name__ == "__main__":
    main()
